// file: models/counter_model.dart
import 'package:flutter/foundation.dart';

class CounterModel with ChangeNotifier {
  int _count = 0;

  // Getter to allow widgets to read the count
  int get count => _count;

  // Method to update the state
  void increment() {
    _count++;
    // This is the crucial part: notify all listening widgets to rebuild
    notifyListeners();
  }
}

