// file: widgets/counter_provider.dart
import 'package:flutter/widgets.dart';
import '../models/counter_model.dart';

class CounterProvider extends InheritedWidget {
  final CounterModel model;

  const CounterProvider({
    super.key,
    required this.model,
    required super.child,
  });

  // The convention for easily accessing the provider from descendants.
  static CounterProvider of(BuildContext context) {
    final CounterProvider? result =
        context.dependOnInheritedWidgetOfExactType<CounterProvider>();
    assert(result != null, 'No CounterProvider found in context');
    return result!;
  }

  // This method determines if widgets that depend on this InheritedWidget
  // should be rebuilt when the InheritedWidget itself is rebuilt.
  @override
  bool updateShouldNotify(CounterProvider oldWidget) {
    // We compare the model instance. If it's a new instance,
    // dependents should be notified. In our simple case, this might not
    // be strictly necessary as the ChangeNotifier handles notifications,
    // but it's good practice.
    return model != oldWidget.model;
  }
}

