// file: screens/home_screen.dart
import 'package:flutter/material.dart';
import '../models/counter_model.dart';
import '../widgets/counter_provider.dart';

class HomeScreen extends StatelessWidget {
  const HomeScreen({super.key});

  @override
  Widget build(BuildContext context) {
    // Get the model from the provider.
    final counterModel = CounterProvider.of(context).model;

    return Scaffold(
      appBar: AppBar(
        title: const Text('State Management Demo'),
      ),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: <Widget>[
            const Text(
              'You have pushed the button this many times:',
            ),
            // Use ListenableBuilder to only rebuild the Text widget
            // when the counterModel notifies its listeners.
            ListenableBuilder(
              listenable: counterModel,
              builder: (BuildContext context, Widget? child) {
                return Text(
                  '${counterModel.count}',
                  style: Theme.of(context).textTheme.headlineMedium,
                );
              },
            ),
          ],
        ),
      ),
      floatingActionButton: FloatingActionButton(
        // We can access the model directly to call methods.
        onPressed: () => counterModel.increment(),
        tooltip: 'Increment',
        child: const Icon(Icons.add),
      ),
    );
  }
}
